typedef unsigned long long big_int;

class stringx;

class string_buf
{
  friend class stringx;
  friend bool operator==(const stringx&, const stringx&);

  big_int* data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;

public:
  bool is_equal(const string_buf& buf) const
  {
    if (buf.block_length != block_length)
      return false;
    for (int i = 0; i < block_length; i++)
      if (!(buf.data[i] == data[i]))
        return false;
    return true;
  }
};

class stringx
{
  friend bool operator==(const stringx&, const stringx&);

  char* chars;
  string_buf* my_buf;

public:
  stringx();
  stringx(const stringx&);
  stringx(const char*, int len = -1);
  ~stringx();
  void append(const char*, int len = -1);
  void append(const stringx&);
};

inline bool operator==(const stringx& lhs, const stringx& rhs)
{
  return lhs.my_buf->is_equal(*rhs.my_buf);
}

stringx operator+(const stringx& lhs, const char* rhs)
{
  stringx result;
  result.append(lhs);
  result.append(rhs);
  return result;
}

void error(const stringx&);

class chunk_file;

class entity_id
{
  void* value[2];

public:
  const stringx& get_val() const;
};

enum entity_flavor_t
{
  ENTITY_SCANNER = 13
};

class entity
{
  char base_prefix[120];
  entity_flavor_t flavor;
  entity_id id;
  char base_suffix[376];

public:
  entity_flavor_t get_flavor() const { return flavor; }
  const entity_id& get_id() const { return id; }
  virtual bool parse_instance(const stringx&, chunk_file&);
};

template <class T>
class vector
{
public:
  typedef T* iterator;

private:
  iterator start;
  iterator finish;
  iterator end_of_storage;

public:
  iterator begin() { return start; }
  iterator end() { return finish; }
};

typedef vector<entity*> pentity_vector;

class conglomerate : public entity
{
  pentity_vector members;

public:
  bool parse_instance(const stringx&, chunk_file&);
};

bool conglomerate::parse_instance(const stringx& pcf, chunk_file& fs)
{
  if (pcf == stringx("scanner"))
  {
    pentity_vector::iterator i = members.begin();
    pentity_vector::iterator i_end = members.end();
    for (; i != i_end; i++)
    {
      if ((*i)->get_flavor() == ENTITY_SCANNER)
        break;
    }
    if (i == i_end)
      error(get_id().get_val() + ": parse_instance(): no scanner member found in conglomerate");
    else
      return (*i)->parse_instance(pcf, fs);
  }
  else
    return entity::parse_instance(pcf, fs);
  return false;
}
